import {createRun,context,getScene,applyChoice,encodeRun,decodeRun,effectPreview,statsMeta,gear,MAX_TURNS} from './survival.mjs';
import {artwork} from './survival-art.mjs';
const $=id=>document.getElementById(id),KEY='ten-minutes-left-v2';
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={hp:'체력',cash:'동전',wit:'잔머리',trust:'신뢰',heat:'악명'};
let state,archive=[],pending=false,sound=false,audio=null,isShared=false,toastTimer,storageWorks=true;
function seed(){return [...crypto.getRandomValues(new Uint8Array(8))].map(n=>n.toString(16).padStart(2,'0')).join('');}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3600);}
function storageFailed(){storageWorks=false;document.querySelector('.auto-save').textContent='저장 불가 · 이번 판만';}
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved){if(Array.isArray(saved.archive))archive=saved.archive.filter(r=>r&&typeof r.code==='string'&&/^2\.[a-f0-9]{16}\.[0-3]{1,10}$/.test(r.code)&&Number.isFinite(r.at));if(typeof saved.current==='string')try{state=decodeRun(saved.current);}catch{toast('이전 진행 기록을 복원하지 못해 새로운 재난을 시작했어요.');}}}catch{storageFailed();}
state??=createRun(seed());
const shared=new URLSearchParams(location.search).get('run');
if(shared){try{const imported=decodeRun(shared);if(!imported.ending)throw Error('Incomplete record');state=imported;isShared=true;}catch{toast('공유 링크가 올바르지 않아요. 내 게임을 이어갑니다.');}}
function persist(){if(isShared)return;try{localStorage.setItem(KEY,JSON.stringify({current:encodeRun(state),archive}));}catch{storageFailed();toast('브라우저에 기록을 저장하지 못했어요. 현재 게임은 계속할 수 있어요.');}}
function recordEnding(){if(!state.ending||isShared)return;const code=encodeRun(state);if(!archive.some(r=>r.code===code))archive.unshift({code,at:Date.now()});persist();}
function effectTags(delta){return Object.entries(delta).filter(([,v])=>v).map(([key,value])=>`<span class="effect ${key==='heat'?(value>0?'negative':''):(value<0?'negative':'')}">${labels[key]} ${value>0?'+':''}${value}</span>`).join('');}
function ping(end=false){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='triangle';osc.frequency.setValueAtTime(end?440:620,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(end?220:360,audio.currentTime+.18);gain.gain.setValueAtTime(.025,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.3);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.35);}catch{sound=false;updateSound();toast('이 브라우저에서는 소리를 사용할 수 없어요.');}}
function updateSound(){$('sound').innerHTML=sound?'♪':'♪<span>×</span>';$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'효과음 끄기':'효과음 켜기');}
function chrome(){document.querySelector('.auto-save').textContent=isShared?'공유 기록 읽기':storageWorks?'● 자동 저장':'저장 불가 · 이번 판만';$('mobile-stats').innerHTML=statsMeta.map(m=>`<span class="${(m.key==='hp'&&state.hp<=3)||(m.key==='trust'&&state.trust<0)?'danger':''}">${m.label}<b>${state[m.key]}</b></span>`).join('');const x=context(state);$('disaster-badge').textContent=x.disaster.badge;$('clock').textContent=`${String(Math.max(0,MAX_TURNS-state.step)).padStart(2,'0')}:00`;$('progress-label').textContent=`${String(state.step).padStart(2,'0')} / 10 CHOICES`;$('progress-dots').innerHTML=Array.from({length:10},(_,i)=>`<i class="${i<state.step?'filled':''}"></i>`).join('');$('archive-count').textContent=archive.length;$('stats').innerHTML=statsMeta.map(m=>`<div class="stat ${(m.key==='hp'&&state.hp<=3)||(m.key==='trust'&&state.trust<0)?'low':''}"><div class="stat-top"><span>${m.label}</span><i aria-hidden="true">${m.icon}</i></div><div class="stat-value">${state[m.key]}${m.key==='hp'?'<small> / 12</small>':''}</div><div class="stat-bar" role="meter" aria-label="${m.label}" aria-valuemin="${m.key==='trust'?-20:0}" aria-valuemax="${m.key==='hp'?12:m.key==='cash'?999:20}" aria-valuenow="${state[m.key]}"><i style="width:${Math.min(100,Math.abs(state[m.key])/m.max*100)}%"></i></div></div>`).join('');$('heat-value').textContent=state.heat;$('heat-hint').textContent=state.heat>=6?'얼굴이 꽤 알려졌어요':state.heat>=3?'누군가 찾고 있어요':'아직 무명 시민';$('item-count').textContent=`${state.items.length}개`;$('items').innerHTML=state.items.length?state.items.map(id=>`<button class="item" data-item="${id}" title="${esc(gear[id].hint)}"><b aria-hidden="true">${gear[id].icon}</b>${gear[id].name}</button>`).join(''):'<p class="empty">비어 있는 주머니.<br>가벼워진 만큼, 선택은 무거워집니다.</p>';$('items').querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const g=gear[b.dataset.item];openModal(`<h2>${g.icon} ${g.name}</h2><p>${g.hint}</p><div class="rule-box"><p>상황이 맞으면 네 번째 선택지로 사용할 수 있어요. 승차권·연료·허가증·무전기는 마지막 선택에도 영향을 줍니다.</p></div>`);});$('crew-count').textContent=`${state.companions.length}명`;$('crew').innerHTML=state.companions.length?state.companions.map(c=>`<div class="crew-person"><span class="crew-avatar">${c.id==='snail'?'@':'☺'}</span><div><b>${esc(c.name)}</b><small>${esc(c.role)}</small></div></div>`).join(''):`<p class="empty">${state.departed.length?'동료들은 당신을 떠났습니다.':'아직 혼자예요. 혼자면 빠르지만…'}</p>`;$('history-count').textContent=`${state.step} / 10`;$('history').innerHTML=state.history.length?state.history.slice(-3).map(h=>`<div><time>${String(h.turn).padStart(2,'0')}</time><span>${esc(h.choice)}</span></div>`).join(''):'<p class="empty">첫 선택이 아직 남아 있습니다.</p>';if(!storageWorks)storageFailed();}
function focusStory(){$('story-copy').focus({preventScroll:true});document.querySelector('.game-card').scrollIntoView({block:'start',behavior:'instant'});}
function render(focus=false){pending=false;chrome();document.querySelector('.game-card').classList.toggle('ending-mode',!!state.ending);$('reaction').hidden=true;$('reaction').replaceChildren();$('choices').hidden=false;$('choices').replaceChildren();$('story-copy').classList.remove('fade-in');void $('story-copy').offsetWidth;$('story-copy').classList.add('fade-in');const x=context(state);$('shared-banner').hidden=!isShared;if(isShared){$('shared-banner').innerHTML='<span>공유받은 생존 기록을 보고 있어요. 내 진행 기록은 그대로 남아 있어요.</span><button id="shared-retry">같은 재난에 도전</button>';$('shared-retry').onclick=()=>start(state.seed);}if(state.ending){renderEnding();if(focus)focusStory();return;}
  const sc=getScene(state);$('turn-label').textContent=`ROUND ${String(state.step+1).padStart(2,'0')} / 10`;$('scene-tag').textContent=sc.tag;$('world-label').textContent=`${x.city} · ${x.disaster.name}`;$('scene-title').textContent=sc.title;$('scene-text').textContent=sc.text;$('illustration').innerHTML=artwork(sc.art,x.disaster.id);$('decision-label').textContent=state.step===9?'마지막 한 번, 당신의 선택.':'이번에는, 어떻게 할까요?';$('key-hint').textContent=sc.choices.length===4?'KEY 1 · 2 · 3 · 4':'KEY 1 · 2 · 3';
  sc.choices.forEach((ch,i)=>{const b=document.createElement('button');b.className=`choice ${ch.special?'special':''}`;b.disabled=ch.disabled;b.innerHTML=`<span class="choice-key">${i+1}</span><span class="choice-copy"><span class="choice-title">${esc(ch.title)}${ch.special?'<span class="unlock-label">SPECIAL</span>':''}</span><span class="choice-desc">${esc(ch.disabledReason||ch.desc)}</span><span class="choice-effects">${effectTags(effectPreview(state,ch))}${ch.check?`<span class="effect ${state[ch.check.stat]>=ch.check.min?'':'negative'}">${state[ch.check.stat]>=ch.check.min?'조건 충족':'조건 미달'}</span>`:''}</span></span><span class="choice-arrow" aria-hidden="true">↗</span>`;b.onclick=()=>pick(i);$('choices').append(b);});if(focus)focusStory();}
function pick(index){if(pending||state.ending||$('modal').open)return;const sc=getScene(state),ch=sc.choices[index];if(!ch||ch.disabled){toast(ch?.disabledReason||'지금은 고를 수 없는 선택이에요.');return;}pending=true;const oldCrew=state.companions.length;state=applyChoice(state,index);if(state.ending)recordEnding();else persist();chrome();ping(!!state.ending);$('choices').hidden=true;$('reaction').hidden=false;const h=state.history.at(-1);$('reaction').innerHTML=`<span class="reaction-kicker">CHOICE COMMITTED · 1 MINUTE LATER</span><h3>${esc(h.choice)}</h3><p>${esc(h.reply)}</p><div class="reaction-tags">${effectTags(h.delta)}${h.gained.map(id=>`<span class="effect">+ ${gear[id].name}</span>`).join('')}${h.lost.map(id=>`<span class="effect negative">− ${gear[id].name}</span>`).join('')}${oldCrew>state.companions.length?'<span class="effect negative">동료 이탈</span>':''}${ch.schedule?'<span class="effect">이 선택은 나중에 돌아옵니다</span>':''}</div><button id="continue" class="continue"><span>${state.ending?'내 생존 기록 확인하기':state.step===9?'마지막 1분으로':'다음 1분으로'}</span><span aria-hidden="true">→</span></button>`;$('continue').onclick=()=>render(true);$('continue').focus({preventScroll:true});$('reaction').scrollIntoView({block:'nearest',behavior:'instant'});}
function timeline(s){return `<details class="full-history"><summary>선택 ${s.step}개의 전체 기록 펼치기</summary><ol>${s.history.map(h=>`<li><b>${esc(h.choice)}</b><p>${esc(h.reply)}</p></li>`).join('')}</ol></details>`;}
function endingPaper(s){return `<div class="ending-paper">${s.ending.paragraphs.slice(1).map(p=>`<p>${esc(p)}</p>`).join('')}</div><div class="ending-score"><span>나의 종말 결산 <strong>${s.ending.score}</strong><small> 점</small></span><span>선택 ${s.step}번 · 동료 ${s.companions.length}명 · ${s.ending.outcome}</span></div>`;}
function renderEnding(){const e=state.ending,x=context(state);$('turn-label').textContent=`FINAL RECORD / ${e.grade}`;$('scene-tag').textContent=e.outcome;$('world-label').textContent=`${e.city} · ${e.world}`;$('scene-title').textContent=e.title;$('scene-text').textContent=e.paragraphs[0];$('illustration').innerHTML=artwork('finale',x.disaster.id,true);$('decision-label').textContent='이 결말을 만든 건, 당신의 선택.';$('key-hint').textContent='YOUR CHOICES. YOUR ENDING.';$('choices').innerHTML=endingPaper(state)+`<div class="ending-actions"><button id="ending-new" class="primary">새로운 재난 시작 ↗</button><button id="ending-share">이 결말 공유하기</button><button id="ending-archive">생존 기록 보기</button></div>`+timeline(state)+`<div class="restart-row"><button id="ending-retry">같은 재난, 다른 선택으로 다시 해보기 ↻</button></div>`;$('ending-new').onclick=()=>start();$('ending-retry').onclick=()=>start(state.seed);$('ending-share').onclick=()=>share(state);$('ending-archive').onclick=()=>showArchive();}
function openModal(html){$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function clearShared(){if(isShared||new URLSearchParams(location.search).has('run')){const url=new URL(location.href);url.searchParams.delete('run');history.replaceState({},'',url);}isShared=false;}
function start(fixedSeed){clearShared();state=createRun(fixedSeed||seed());if($('modal').open)$('modal').close();persist();render(true);}
function requestNew(){if(!state.step||state.ending){start();return;}openModal('<h2>이 재난은 여기까지?</h2><p>진행 중인 판을 끝내고 새로운 재난을 시작합니다. 이미 완성한 생존 기록은 남아 있어요.</p><div class="ending-actions"><button class="primary" id="confirm-new">새 재난 시작</button><button id="cancel-new">지금 판 계속하기</button></div>');$('confirm-new').onclick=()=>start();$('cancel-new').onclick=()=>$('modal').close();}
function showArchive(page=0){const pageSize=6,total=Math.ceil(archive.length/pageSize);openModal(`<h2>어떻게든, 살아 보려고.</h2><p>완성한 생존 기록 ${archive.length}개. 정해진 수집 개수나 마지막 결말은 없어요.</p>${!archive.length?'<div class="rule-box"><b>아직 마지막 장면에 도착하지 않았어요.</b><p>한 판을 마치면 재난, 선택, 동료와 소지품이 반영된 기록이 여기에 쌓입니다.</p></div>':'<div id="archive-grid" class="archive-grid"></div><div class="archive-pagination"><button id="archive-prev">← 이전</button><span>'+`${page+1} / ${total}`+'</span><button id="archive-next">다음 →</button></div>'}<p style="font-size:10px">기록은 현재 브라우저에 저장됩니다. 브라우저 데이터를 삭제하면 사라집니다.</p>`);if(!archive.length)return;archive.slice(page*pageSize,(page+1)*pageSize).forEach((r,i)=>{try{const s=decodeRun(r.code);if(!s.ending)return;const b=document.createElement('button');b.className='archive-tile';b.innerHTML=`<small>RECORD ${String(archive.length-page*pageSize-i).padStart(3,'0')} / ${s.ending.grade}</small><b>${esc(s.ending.title)}</b><span>${esc(s.ending.world)} · ${s.step}번의 선택 · ${s.ending.score}점</span>`;b.onclick=()=>showRecord(s,page);$('archive-grid').append(b);}catch{/* Ignore an invalid individual record. */}});$('archive-prev').disabled=page===0;$('archive-next').disabled=page>=total-1;$('archive-prev').onclick=()=>showArchive(page-1);$('archive-next').onclick=()=>showArchive(page+1);}
function showRecord(s,page){openModal(`<div class="ending-grade" style="margin-top:20px">${s.ending.grade} / ${esc(s.ending.outcome)}</div><h2>${esc(s.ending.title)}</h2><p>${esc(s.ending.paragraphs[0])}</p>${endingPaper(s)}${timeline(s)}<div class="ending-actions"><button class="primary" id="archive-back">목록으로</button><button id="archive-share">이 결말 공유</button><button id="archive-retry">같은 재난 도전</button></div>`);$('archive-back').onclick=()=>showArchive(page);$('archive-share').onclick=()=>share(s);$('archive-retry').onclick=()=>{if(state.step&&!state.ending){const targetSeed=s.seed;openModal('<h2>이 기록의 재난에 도전할까요?</h2><p>진행 중인 판은 처음부터 시작합니다. 완성한 기록은 유지됩니다.</p><div class="ending-actions"><button class="primary" id="confirm-retry">같은 재난 도전</button><button id="cancel-retry">돌아가기</button></div>');$('confirm-retry').onclick=()=>start(targetSeed);$('cancel-retry').onclick=()=>showRecord(s,page);}else start(s.seed);};}
async function share(s){const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('run',encodeRun(s));const text=`멸망 10분 전 — 「${s.ending.title}」\n${s.ending.outcome} / ${s.ending.score}점\n내 선택으로 만든 결말이에요. 같은 재난에서 당신은?\n${url.href}`;try{if(navigator.share)await navigator.share({title:'멸망 10분 전',text});else if(navigator.clipboard){await navigator.clipboard.writeText(text);toast('이 결말을 재생하는 링크를 복사했어요.');}else manualCopy(text);}catch(e){if(e.name!=='AbortError')manualCopy(text);}}
function manualCopy(text){openModal('<h2>이 결말을 공유하세요.</h2><p>내용을 복사하면 같은 결말과 선택 경로를 친구도 볼 수 있어요.</p><textarea class="share-text" id="share-text" readonly aria-label="공유할 생존 기록"></textarea>');$('share-text').value=text;$('share-text').focus();$('share-text').select();}
function howEndings(){openModal('<h2>같은 종말, 다른 뒷이야기.</h2><p>고정된 8개 결말 대신, 플레이 기록을 조합해서 결말의 내용을 구성합니다.</p><div class="rule-box"><b>앞선 행동이 실제로 돌아옵니다.</b><p>훔친 가방의 주인, 빌려준 돈, 도운 사람이 몇 번의 선택 뒤에 다시 등장해요. 소지품은 새로운 선택지를 열고, 신뢰가 무너지면 동료가 떠납니다.</p></div><div class="rule-box"><b>마지막 문도 준비에 따라 달라집니다.</b><p>허가증·신뢰는 방공호, 무전기·잔머리는 재난 협상, 표·연료·돈은 탈출에 영향을 줘요. 동료와 배신, 남은 물건, 실제 선택이 결말의 문장에 반영됩니다.</p></div><p>재난과 사건의 순서는 매 판 달라집니다. 정해진 사건·인물·문구를 조합하는 방식이라 일부 내용은 반복될 수 있어요. AI가 실시간으로 새 문장을 생성하는 방식은 아닙니다. 플레이 횟수나 결말 수집 개수에 제한은 두지 않았어요.</p>');}
function help(){openModal('<h2>멸망을 대하는 자세.</h2><p>한 번의 선택이 1분입니다. 실제로 서두를 필요는 없어요.</p><ul><li>각 상황에서 세 가지 선택 중 하나를 골라 주세요.</li><li>아이템이나 관계가 맞으면 네 번째 특별 선택이 열려요.</li><li>동전이 모자라면 구매할 수 없고, 체력이 0이면 그 자리에서 기록이 끝납니다.</li><li>잔머리·신뢰 조건은 선택 전에 보입니다. 조건 미달의 대가도 확인하세요.</li><li>체력은 최대 12, 잔머리·악명은 최대 20, 신뢰는 -20~20입니다. 추가 회복은 한도까지만 적용됩니다.</li><li>열 번째 선택은 방공호·재난 협상·탈출·다른 미래 중 하나입니다.</li><li>숫자 1·2·3·4로 선택하고 Enter로 다음 장면에 갈 수 있어요.</li><li>진행 상황과 결말은 이 브라우저에 저장됩니다. 기기 간 동기화는 없어요.</li></ul><p>효과음은 기본 꺼짐. 광고, 결제, 로그인 없이 플레이할 수 있어요.</p>');}
$('help').onclick=help;$('how-endings').onclick=howEndings;$('archive').onclick=()=>showArchive();$('new-run').onclick=requestNew;$('sound').onclick=()=>{sound=!sound;updateSound();if(sound)ping();};$('close-modal').onclick=()=>$('modal').close();$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}});document.addEventListener('keydown',e=>{if($('modal').open||pending||state.ending||e.repeat||e.ctrlKey||e.metaKey||e.altKey||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(['1','2','3','4'].includes(e.key)){e.preventDefault();pick(Number(e.key)-1);}});recordEnding();render();
